CREATE TABLE agent_graph_events (
            run_id        TEXT NOT NULL,
            session_id    TEXT NOT NULL DEFAULT '',
            node_id       TEXT NOT NULL DEFAULT '',
            seq           INTEGER NOT NULL,
            kind          TEXT NOT NULL,
            payload_json  TEXT NOT NULL DEFAULT 'null',
            ts_ns         INTEGER NOT NULL,
            PRIMARY KEY (run_id, seq)
        );

CREATE TABLE agent_graph_node_provenance (
            graph_id                    TEXT NOT NULL,
            node_id                     TEXT NOT NULL,
            kind                        TEXT NOT NULL DEFAULT '',
            manifest_version_at_author  TEXT NOT NULL DEFAULT '',
            fingerprint_at_author       TEXT NOT NULL DEFAULT '',
            PRIMARY KEY (graph_id, node_id)
        );

CREATE TABLE artifact_versions (
            id           INTEGER PRIMARY KEY AUTOINCREMENT,
            artifact_id  TEXT NOT NULL REFERENCES artifacts(id) ON DELETE CASCADE,
            version      INTEGER NOT NULL,
            content_hash TEXT NOT NULL,
            byte_size    INTEGER NOT NULL,
            mime_type    TEXT NOT NULL DEFAULT '',
            summary      TEXT,
            path         TEXT,
            created_at   INTEGER NOT NULL,
            UNIQUE (artifact_id, version)
        );

CREATE TABLE "artifacts" (
                    id              TEXT PRIMARY KEY,
                    session_id      TEXT NULL REFERENCES sessions(id) ON DELETE SET NULL,
                    project_id      TEXT NULL REFERENCES projects(id) ON DELETE SET NULL,
                    title           TEXT NOT NULL DEFAULT '',
                    mime_type       TEXT NOT NULL,
                    content_hash    TEXT NOT NULL,
                    byte_size       INTEGER NOT NULL,
                    source          TEXT NOT NULL CHECK (source IN ('code_block','tool_output','user_pin','model_output')),
                    source_ref_json TEXT NOT NULL DEFAULT '{}',
                    scope_kind      TEXT NOT NULL DEFAULT 'session' CHECK (scope_kind IN ('session','project','global')),
                    created_at      INTEGER NOT NULL
                );

CREATE TABLE branch_message_refs (
            branch_id       TEXT NOT NULL REFERENCES branches(id) ON DELETE CASCADE,
            seq             INTEGER NOT NULL,
            parent_msg_id   TEXT NOT NULL,
            child_msg_id    TEXT NOT NULL DEFAULT '',
            PRIMARY KEY (branch_id, seq)
        );

CREATE TABLE branches (
            id                  TEXT PRIMARY KEY,
            parent_session_id   TEXT NOT NULL REFERENCES sessions(id) ON DELETE CASCADE,
            child_session_id    TEXT NOT NULL REFERENCES sessions(id) ON DELETE CASCADE,
            kind                TEXT NOT NULL DEFAULT 'fork',
            status              TEXT NOT NULL DEFAULT 'active',
            model_id            TEXT NOT NULL DEFAULT '',
            provider_id         TEXT NOT NULL DEFAULT '',
            title               TEXT NOT NULL DEFAULT '',
            task_hint           TEXT NOT NULL DEFAULT '',
            created_at          INTEGER NOT NULL,
            updated_at          INTEGER NOT NULL,
            merged_at           INTEGER,
            abandoned_at        INTEGER
        , subagent_branch INTEGER NOT NULL DEFAULT 0, recommendation_id TEXT NOT NULL DEFAULT '', advisor_signals TEXT NOT NULL DEFAULT '[]', parent_message_id TEXT NOT NULL DEFAULT '', branch_title TEXT NOT NULL DEFAULT '', creation_path TEXT NOT NULL DEFAULT 'unknown', parent_session_title TEXT NOT NULL DEFAULT '');

CREATE TABLE context_attachments (
            id              TEXT PRIMARY KEY,
            scope_kind      TEXT NOT NULL CHECK (scope_kind IN ('global','project','session')),
            scope_id        TEXT NOT NULL,
            content_source  TEXT NOT NULL,
            content         TEXT NOT NULL,
            kind            TEXT NOT NULL DEFAULT 'system',
            position        INTEGER NOT NULL DEFAULT 0,
            created_at      INTEGER NOT NULL
        , media_id TEXT NULL
            REFERENCES media_artifacts(id) ON DELETE SET NULL);

CREATE TABLE corpora (
            id          TEXT PRIMARY KEY,
            name        TEXT NOT NULL,
            scope       TEXT NOT NULL CHECK (scope IN ('global','project','session')),
            scope_id    TEXT NOT NULL DEFAULT '',
            tag         TEXT NOT NULL DEFAULT '',
            created_at  INTEGER NOT NULL,
            updated_at  INTEGER NOT NULL
        );

CREATE TABLE corpus_chunks (
            id          TEXT PRIMARY KEY,
            corpus_id   TEXT NOT NULL REFERENCES corpora(id) ON DELETE CASCADE,
            file_id     TEXT NOT NULL REFERENCES corpus_files(id) ON DELETE CASCADE,
            chunk_seq   INTEGER NOT NULL,
            text        TEXT NOT NULL,
            embedding   BLOB NOT NULL,
            line_start  INTEGER NOT NULL,
            line_end    INTEGER NOT NULL,
            created_at  INTEGER NOT NULL
        );

CREATE TABLE corpus_files (
            id            TEXT PRIMARY KEY,
            corpus_id     TEXT NOT NULL REFERENCES corpora(id) ON DELETE CASCADE,
            path          TEXT NOT NULL,
            sha256        TEXT NOT NULL,
            file_size     INTEGER NOT NULL,
            line_count    INTEGER NOT NULL,
            ingested_at   INTEGER NOT NULL
        );

CREATE TABLE cost_threshold_fired (
