            hash         TEXT NOT NULL,
            created_at   INTEGER NOT NULL,
            updated_at   INTEGER NOT NULL
        );

CREATE TRIGGER events_ai AFTER INSERT ON events BEGIN
    INSERT INTO events_fts(rowid, payload) VALUES (new.rowid, new.payload);
END;

CREATE TRIGGER events_fts_ad AFTER DELETE ON events BEGIN
    INSERT INTO events_fts(events_fts, rowid, payload) VALUES ('delete', old.rowid, old.payload);
END;

CREATE TRIGGER events_fts_au AFTER UPDATE ON events BEGIN
    INSERT INTO events_fts(events_fts, rowid, payload) VALUES ('delete', old.rowid, old.payload);
    INSERT INTO events_fts(rowid, payload) VALUES (new.rowid, new.payload);
END;

CREATE TRIGGER messages_fts_ad
    AFTER DELETE ON session_messages WHEN old.role <> 'tool' BEGIN
        INSERT INTO messages_fts(messages_fts, rowid, content)
            VALUES ('delete', old.rowid, old.content);
    END;

CREATE TRIGGER messages_fts_ai
    AFTER INSERT ON session_messages WHEN new.role <> 'tool' BEGIN
        INSERT INTO messages_fts(rowid, content)
            VALUES (new.rowid, new.content);
    END;

CREATE TRIGGER messages_fts_au
    AFTER UPDATE ON session_messages BEGIN
        INSERT INTO messages_fts(messages_fts, rowid, content)
            SELECT 'delete', old.rowid, old.content WHERE old.role <> 'tool';
        INSERT INTO messages_fts(rowid, content)
            SELECT new.rowid, new.content WHERE new.role <> 'tool';
    END;

